            added.add(element)
    return result

from collections import defaultdict

def count_valid_paths(n):
    if n == 1:
        return 1
    steps = 2 * (n - 1)
    current = {0: 1}
    for _ in range(steps):
        next_state = defaultdict(int)
        for diff, count in current.items():
            # Add right move if allowed
            if diff < 1:
                new_diff = diff + 1
                if new_diff <= 1:
                    next_state[new_diff] += count
            # Add down move
            new_diff = diff - 1
            if new_diff >= -(n - 1):
                next_state[new_diff] += count
        current = next_state
    return current.get(0, 0)

