def enhanced_ternary_search(arr: List[int], key: int, return_index: bool) -> Union[int, bool]:
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid1 = (low + high) // 3
        mid2 = (low + 2 * high) // 3
        if arr[mid1] == key:
            return mid1
        if arr[mid2] == key:
            return mid2
        if key < arr[mid1]:
            high = mid1 - 1
        elif key > arr[mid2]:
            low = mid2 + 1
        else:
            low = mid1 + 1
            high = mid2 - 1
    if return_index:
