    if not arr:
        return 0
    n = len(arr)
    left_max = [0] * n
    right_max = [0] * n

    left_max[0] = arr[0]
    for i in range(1, n):
        left_max[i] = max(left_max[i-1], arr[i])

    right_max[-1] = arr[-1]
    for i in range(n-2, -1, -1):
