def has_cycle(graph: dict[str, list[str]]) -> bool:
    visited = set()
    recursion_stack = set()

    def dfs(node):
        visited.add(node)
        recursion_stack.add(node)
        for neighbor in graph[node]:
            if neighbor in recursion_stack:
                return True
            if neighbor not in visited:
                if dfs(neighbor):
                    return True
        recursion_stack.remove(node)
        return False

    for node in graph:
        if node not in visited:
            if dfs(node):
                return True
    return False

