def decode(encoded_str):
    result = []
    index = 0
    n = len(encoded_str)
    while index < n:
        # Read the length
        start = index
        while index < n and encoded_str[index].isdigit():
            index += 1
        if start == index:
            length = 0
        else:
            length = int(encoded_str[start:index])
        # Move past the colon
        if index < n and encoded_str[index] == ':':
            index += 1
        # Read the string
        if length == 0:
            s = ''
        else:
            s = encoded_str[index:index + length]
        result.append(s)
        index += length
    return result

