def is_path_exist(vertex_count: int, edges: List[Tuple[int, int]], source: int, target: int) -> bool:
    if source == target:
        return True

    # Build adjacency list
    adj = [[] for _ in range(vertex_count)]
    for u, v in edges:
        adj[u].append(v)

    # BFS initialization
    visited = [False] * vertex_count
    queue = deque()
    queue.append(source)
    visited[source] = True

    while queue:
        current = queue.popleft()
        for neighbor in adj[current]:
            if not visited[neighbor]:
                if neighbor == target:
                    return True
                visited[neighbor] = True
                queue.append(neighbor)

    return False

