def climb_stairs_extended(total_steps: int) -> int:
    if total_steps == 0:
        return 0
    elif total_steps == 1:
        return 1
    elif total_steps == 2:
        return 2
    elif total_steps == 3:
        return 4
    else:
        dp = [0] * (total_steps + 1)
        dp[0] = 0
        dp[1] = 1
        dp[2] = 2
        dp[3] = 4
        for i in range(4, total_steps + 1):
            dp[i] = dp[i-1] + dp[i-2] + dp[i-3]
        return dp[total_steps]

